import { useState } from "react";
import { Link, useNavigate } from "react-router-dom";

export default function Register() {
  const navigate = useNavigate();

  const [user, setUser] = useState({
    name: "",
    email: "",
    password: "",
    role: "Student",
  });

  const [generatedOtp, setGeneratedOtp] = useState("");
  const [enteredOtp, setEnteredOtp] = useState("");
  const [otpVerified, setOtpVerified] = useState(false);

  const handleChange = (e) => {
    setUser({
      ...user,
      [e.target.name]: e.target.value,
    });
  };

  const sendOtp = () => {
    if (!user.email) {
      alert("Please Enter Email First");
      return;
    }

    const otp = Math.floor(
      100000 + Math.random() * 900000
    ).toString();

    setGeneratedOtp(otp);

    alert("OTP Sent Successfully ✅\nOTP : " + otp);
  };

  const verifyOtp = () => {
    if (enteredOtp === generatedOtp) {
      setOtpVerified(true);
      alert("OTP Verified Successfully ✅");
    } else {
      alert("Invalid OTP ❌");
    }
  };

  const handleRegister = (e) => {
    e.preventDefault();

    if (!otpVerified) {
      alert("Please Verify OTP First");
      return;
    }

    const passwordRegex =
      /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]{8,}$/;

    if (!passwordRegex.test(user.password)) {
      alert(
        "Password must contain:\n\n" +
          "• Minimum 8 Characters\n" +
          "• One Uppercase Letter\n" +
          "• One Lowercase Letter\n" +
          "• One Number\n" +
          "• One Special Character"
      );
      return;
    }

    localStorage.setItem(
      "user",
      JSON.stringify(user)
    );

    alert("Registration Successful ✅");

    navigate("/login");
  };

  return (
    <div
      style={{
        minHeight: "100vh",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        background:
          "linear-gradient(135deg,#0f172a,#1e3a8a,#7c3aed)",
        padding: "20px",
      }}
    >
      <form
        onSubmit={handleRegister}
        style={{
          width: "450px",
          background: "#ffffff",
          padding: "40px",
          borderRadius: "24px",
          boxShadow: "0 20px 60px rgba(0,0,0,0.25)",
        }}
      >
        <h1
          style={{
            textAlign: "center",
            color: "#111827",
            marginBottom: "8px",
          }}
        >
          Create Account 🚀
        </h1>

        <p
          style={{
            textAlign: "center",
            color: "#6b7280",
            marginBottom: "30px",
          }}
        >
          Join RBAC Management System
        </p>

        <input
          type="text"
          name="name"
          placeholder="Full Name"
          value={user.name}
          onChange={handleChange}
          style={inputStyle}
          required
        />

        <input
          type="email"
          name="email"
          placeholder="Email Address"
          value={user.email}
          onChange={handleChange}
          style={inputStyle}
          required
        />

        <button
          type="button"
          onClick={sendOtp}
          style={blueBtn}
        >
          Send OTP
        </button>

        <input
          type="text"
          placeholder="Enter OTP"
          value={enteredOtp}
          onChange={(e) =>
            setEnteredOtp(e.target.value)
          }
          style={inputStyle}
        />

        <button
          type="button"
          onClick={verifyOtp}
          style={orangeBtn}
        >
          Verify OTP
        </button>

        {otpVerified && (
          <div
            style={{
              background: "#dcfce7",
              color: "#166534",
              padding: "12px",
              borderRadius: "10px",
              textAlign: "center",
              marginBottom: "15px",
              fontWeight: "600",
            }}
          >
            ✅ OTP Verified Successfully
          </div>
        )}

        <input
          type="password"
          name="password"
          placeholder="Password"
          value={user.password}
          onChange={handleChange}
          style={inputStyle}
          required
        />

        <small
          style={{
            color: "#6b7280",
            display: "block",
            marginBottom: "15px",
          }}
        >
          Password must contain:
          <br />
          ✔ Minimum 8 Characters
          <br />
          ✔ Uppercase Letter
          <br />
          ✔ Lowercase Letter
          <br />
          ✔ Number
          <br />
          ✔ Special Character
        </small>

        <select
          name="role"
          value={user.role}
          onChange={handleChange}
          style={inputStyle}
        >
          <option value="Student">
            Student
          </option>
          <option value="Instructor">
            Instructor
          </option>
          <option value="Admin">
            Admin
          </option>
        </select>

        <button
          type="submit"
          style={greenBtn}
        >
          Register Account
        </button>

        <p
          style={{
            textAlign: "center",
            marginTop: "20px",
          }}
        >
          Already have an account?{" "}
          <Link
            to="/login"
            style={{
              color: "#2563eb",
              textDecoration: "none",
              fontWeight: "600",
            }}
          >
            Login
          </Link>
        </p>
      </form>
    </div>
  );
}

const inputStyle = {
  width: "100%",
  padding: "14px 16px",
  marginBottom: "14px",
  border: "1px solid #d1d5db",
  borderRadius: "12px",
  outline: "none",
  fontSize: "15px",
  boxSizing: "border-box",
};

const blueBtn = {
  width: "100%",
  padding: "14px",
  background:
    "linear-gradient(90deg,#2563eb,#3b82f6)",
  color: "white",
  border: "none",
  borderRadius: "12px",
  cursor: "pointer",
  marginBottom: "14px",
  fontWeight: "600",
};

const orangeBtn = {
  width: "100%",
  padding: "14px",
  background:
    "linear-gradient(90deg,#f59e0b,#f97316)",
  color: "white",
  border: "none",
  borderRadius: "12px",
  cursor: "pointer",
  marginBottom: "14px",
  fontWeight: "600",
};

const greenBtn = {
  width: "100%",
  padding: "15px",
  background:
    "linear-gradient(90deg,#10b981,#059669)",
  color: "white",
  border: "none",
  borderRadius: "12px",
  cursor: "pointer",
  marginTop: "15px",
  fontSize: "16px",
  fontWeight: "700",
};
